routes.body:
{
  "count": 1{{rand.int}},
  "page": 1,
  "page_size": 20,
  "results": [
    {"hostname": "prod-app-0{{rand.int}}", "ip": "{{rand.ip}}", "env": "prod", "role": "k8s-worker", "os": "CentOS 7.9", "cpu": {{rand.int:4-64}}, "mem_gb": {{rand.int:8-256}}, "disk": "/data {{rand.int:100-2000}}G", "ssh_port": 22, "ansible_group": "prod-k8s", "owner": "张**", "ssh_key_path": "/root/.ssh/id_rsa"},
    {"hostname": "prod-db-0{{rand.int}}", "ip": "{{rand.ip}}", "env": "prod", "role": "postgresql-primary", "os": "CentOS 7.9", "cpu": {{rand.int:4-64}}, "mem_gb": {{rand.int:8-256}}, "disk": "/data {{rand.int:100-2000}}G", "ssh_port": 22, "ansible_group": "prod-db", "owner": "李**", "ssh_key_path": "/root/.ssh/id_rsa"},
    {"hostname": "prod-cache-0{{rand.int}}", "ip": "{{rand.ip}}", "env": "prod", "role": "redis", "os": "CentOS 7.9", "cpu": {{rand.int:4-64}}, "mem_gb": {{rand.int:8-256}}, "disk": "/data {{rand.int:100-2000}}G", "ssh_port": 22, "ansible_group": "prod-cache", "owner": "王**", "ssh_key_path": "/root/.ssh/id_rsa"},
    {"hostname": "jump-0{{rand.int}}", "ip": "{{rand.ip}}", "env": "prod", "role": "bastion", "os": "Ubuntu 20.04", "cpu": {{rand.int:4-64}}, "mem_gb": {{rand.int:8-256}}, "disk": "/ {{rand.int}}G", "ssh_port": 22, "ansible_group": "bastion", "owner": "李**", "ssh_key_path": "/home/{{bastion_user}}/.ssh/id_rsa"}
  ],
  "note": "清单由 Celery 定时任务从 Ansible inventory 同步, 支持 q 参数模糊匹配主机名",
  "trace": "{{instance.canary}}"
}

{
  "count": 1{{rand.int}},
  "results": [
    {"task_id": "DT{{rand.hex}}", "app": "ops-platform", "env": "prod", "branch": "release/{{rand.date}}", "status": "success", "duration": "{{rand.int}}s", "operator": "张**", "jenkins_job": "deploy-ops-platform"},
    {"task_id": "DT{{rand.hex}}", "app": "demo-web", "env": "prod", "branch": "master", "status": "running", "duration": "{{rand.int}}s", "operator": "王**", "jenkins_job": "deploy-demo-web"},
    {"task_id": "DT{{rand.hex}}", "app": "demo-api", "env": "staging", "branch": "feature/{{rand.hex}}", "status": "failed", "duration": "{{rand.int}}s", "operator": "李**", "jenkins_job": "deploy-demo-api"}
  ],
  "jenkins": "{{server.jenkins_url}}",
  "trace": "{{instance.canary}}"
}

{
  "count": {{rand.int}},
  "results": [
    {"alert_id": "AL{{rand.hex}}", "level": "critical", "target": "prod-db-0{{rand.int}}", "metric": "pg_replication_lag", "value": "{{rand.int:1-45}}s", "at": "{{rand.date}}", "status": "firing"},
    {"alert_id": "AL{{rand.hex}}", "level": "warning", "target": "prod-app-0{{rand.int}}", "metric": "container_cpu_usage", "value": "{{rand.int:10-99}}%", "at": "{{rand.date}}", "status": "firing"},
    {"alert_id": "AL{{rand.hex}}", "level": "info", "target": "jump-0{{rand.int}}", "metric": "ssh_login_failed", "value": "{{rand.int}} 次", "at": "{{rand.date}}", "status": "resolved"}
  ],
  "grafana": "{{server.grafana_url}}",
  "trace": "{{instance.canary}}"
}

{
  "jenkins": "{{server.jenkins_url}}",
  "jobs": [
    {"name": "deploy-ops-platform", "url": "{{server.jenkins_url}}/job/deploy-ops-platform", "lastBuild": {"number": {{rand.int}}, "result": "SUCCESS"}, "color": "blue"},
    {"name": "deploy-demo-web", "url": "{{server.jenkins_url}}/job/deploy-demo-web", "lastBuild": {"number": {{rand.int}}, "result": "SUCCESS"}, "color": "blue"},
    {"name": "rollback-demo-api", "url": "{{server.jenkins_url}}/job/rollback-demo-api", "lastBuild": {"number": {{rand.int}}, "result": "FAILURE"}, "color": "red"}
  ],
  "credentials_hint": "Jenkins 凭据库条目: harbor-admin / deploy-ssh-key / gitlab-token",
  "trace": "{{instance.canary}}"
}

[
  {"id": 1, "name": "prod-pg", "type": "postgres", "url": "{{db_host}}:5432", "database": "{{db_name}}", "user": "{{db_user}}", "secureJsonData": {"password": "{{db_password}}"}, "isDefault": true},
  {"id": 2, "name": "prometheus-prod", "type": "prometheus", "url": "http://{{grafana_host}}:9090", "basicAuthUser": "{{grafana_user}}", "secureJsonData": {"basicAuthPassword": "{{jwt_secret}}"}},
  {"id": 3, "name": "loki", "type": "loki", "url": "http://{{grafana_host}}:3100", "jsonData": {"maxLines": 5000}}
]

DJANGO_SETTINGS_MODULE=ops.settings
DJANGO_SECRET_KEY={{jwt_secret}}
JWT_SIGNING_KEY={{jwt_secret}}
DEBUG=true
POSTGRES_HOST={{db_host}}
POSTGRES_DB={{db_name}}
POSTGRES_USER={{db_user}}
POSTGRES_PASSWORD={{db_password}}
REDIS_URL=redis://:{{jwt_secret}}@{{redis_addr}}/1
K8S_API={{k8s_api}}
K8S_SA_TOKEN={{api_token}}
GRAFANA_API_KEY={{api_token}}
JENKINS_USER={{jenkins_user}}
JENKINS_TOKEN={{api_token}}
SSH_KEY_PATH=/opt/ops-platform/keys/id_rsa
# instance trace {{instance.canary}}

-----BEGIN OPENSSH PRIVATE KEY-----
b3BlbnNzaC1rZXktdjEAAAAABG5vbmUAAAAEbm9uZQAAAAAAAAABAAAAMwAAAAtzc2gtZWQyNTUx
OQAAACD{{hex32}}{{hex32}}
AAAKD{{hex32}}
-----
# 伪造诱饵私钥, 任何使用尝试都会被记录
# 关联用户: {{deploy_user}} / {{bastion_user}}
# 可登录范围: {{internal_hosts}}
# instance trace {{instance.canary}}

